INSERT INTO university_directions (university_id, direction_id, status, programs, budget_places, program_names)
SELECT v.university_id, v.direction_id, v.status, v.programs::smallint, v.budget_places::integer, v.program_names::text[]
FROM (VALUES
  ('innopolis', 'napr-09-03-01', 'offered', 4, 159, ARRAY['AI360: Инженерия данных','Анализ данных и искусственный интеллект','Инженерия информационных систем','Математические основы искусственного интеллекта']),
  ('innopolis', 'napr-15-03-06', 'offered', 1, 12, ARRAY['Робототехника'])
) AS v(university_id, direction_id, status, programs, budget_places, program_names)
WHERE EXISTS (SELECT 1 FROM universities u WHERE u.id = v.university_id)
ON CONFLICT (university_id, direction_id) DO UPDATE SET
  status = EXCLUDED.status,
  programs = EXCLUDED.programs,
  budget_places = EXCLUDED.budget_places,
  program_names = EXCLUDED.program_names;

-- Выбор учеников: отмеченное у Иннополиса 09.00.00 теперь 09.03.01 — других
-- направлений группы 09 у вуза нет. Цель 09.00.00 (её можно было выбрать в
-- мини-приложении) — туда же: так называется и само направление 09.03.01.
INSERT INTO trajectory_university_directions (trajectory_id, university_id, direction_id, created_at)
SELECT trajectory_id, university_id, 'napr-09-03-01', created_at
FROM trajectory_university_directions
WHERE university_id = 'innopolis' AND direction_id = 'napr-09-00-00'
ON CONFLICT DO NOTHING;

INSERT INTO trajectory_directions (trajectory_id, direction_id, position)
SELECT trajectory_id, 'napr-09-03-01', position FROM trajectory_directions
WHERE direction_id = 'napr-09-00-00'
ON CONFLICT DO NOTHING;
DELETE FROM trajectory_directions WHERE direction_id = 'napr-09-00-00';
UPDATE trajectories SET direction_id = 'napr-09-03-01' WHERE direction_id = 'napr-09-00-00';

DELETE FROM university_directions d USING (VALUES
  ('innopolis', 'napr-09-00-00')
) AS v(university_id, direction_id)
WHERE d.university_id = v.university_id AND d.direction_id = v.direction_id;

