INSERT INTO university_directions (university_id, direction_id, status, programs, budget_places, program_names)
SELECT v.university_id, v.direction_id, v.status, v.programs::smallint, v.budget_places::integer, v.program_names::text[]
FROM (VALUES
  ('innopolis', 'napr-09-00-00', 'offered', 1, 159, ARRAY['Информатика и вычислительная техника'])
) AS v(university_id, direction_id, status, programs, budget_places, program_names)
WHERE EXISTS (SELECT 1 FROM universities u WHERE u.id = v.university_id)
ON CONFLICT (university_id, direction_id) DO UPDATE SET
  status = EXCLUDED.status,
  programs = EXCLUDED.programs,
  budget_places = EXCLUDED.budget_places,
  program_names = EXCLUDED.program_names;

-- Выбор 09.03.01 у Иннополиса — обратно на 09.00.00. Цели остаются 09.03.01:
-- их не отличить от выбранных самим учеником.
INSERT INTO trajectory_university_directions (trajectory_id, university_id, direction_id, created_at)
SELECT trajectory_id, university_id, 'napr-09-00-00', created_at
FROM trajectory_university_directions
WHERE university_id = 'innopolis' AND direction_id = 'napr-09-03-01'
ON CONFLICT DO NOTHING;

